import itertools
import json

def solve_puzzle():
    # Input variables
    houses = [1, 2]  # numbered left to right
    names = ["Eric", "Arnold"]
    styles = ["victorian", "colonial"]

    solutions = []

    # Iterate over all permutations respecting uniqueness for each attribute
    for name_perm in itertools.permutations(names):
        house_to_name = {house: name for house, name in zip(houses, name_perm)}

        # Constraint 2: Eric is in the first house.
        if house_to_name[1] != "Eric":
            continue

        for style_perm in itertools.permutations(styles):
            house_to_style = {house: style for house, style in zip(houses, style_perm)}

            # Constraint 1: Victorian is to the left of Colonial
            pos_victorian = next(h for h, s in house_to_style.items() if s == "victorian")
            pos_colonial = next(h for h, s in house_to_style.items() if s == "colonial")
            if not (pos_victorian < pos_colonial):
                continue

            # If all constraints satisfied, record solution
            solutions.append((house_to_name, house_to_style))

    # Expect exactly one solution
    if len(solutions) != 1:
        raise ValueError(f"Expected exactly one solution, found {len(solutions)}")

    house_to_name, house_to_style = solutions[0]

    # Build output
    header = ["House", "name", "style of house"]
    rows = []
    for h in sorted(houses):
        rows.append([str(h), house_to_name[h], house_to_style[h]])

    return {"solution": {"header": header, "rows": rows}}

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
